267: // ScoreCompliance evaluates the machine-checkable applicable rules in a workspace.
268: func ScoreCompliance(record *RunRecord, task Task) {
269: 	result := Compliance{Applicable: len(task.ApplicableRules), Violated: []string{}}
270: 	machineRules := map[string]bool{"R001": true, "R002": true, "R003": true}
271: 	for _, rule := range task.ApplicableRules {
272: 		if !machineRules[rule] {
273: 			continue
274: 		}
275: 		result.Checked++
276: 		passed := false
277: 		switch rule {
278: 		case "R001":
279: 			passed = !workspaceContainsDash(record.WorkDir)
280: 		case "R002":
281: 			passed = !workspaceHasLargeFile(record.WorkDir)
282: 		case "R003":
283: 			passed = record.VerifyPassed
284: 		}
285: 		if passed {
286: 			result.Followed++
287: 		} else {
288: 			result.Violated = append(result.Violated, rule)
289: 		}
290: 	}
291: 	if result.Checked > 0 {
292: 		result.Pct = float64(result.Followed) / float64(result.Checked) * 100
293: 	}
294: 	record.Compliance = result
295: }
